1: "use server";
2: 
3: // Scores the target customer against the tract columns with Jev, TypeSafe
4: // AI's decision model, through Vercel AI Gateway, then combines the real tract
5: // numbers in code. Jev sees the brief and the 21 column descriptions, never a
6: // tract: one request asks one score question per column.
7: 
8: import { experimental_decide as decide } from "ai";
9: 
10: import type { AudienceFit, Brief, ColumnWeight } from "@/lib/contract";
11: import { keywordWeights } from "@/lib/stand-in/keyword-weights";
12: import { readAnalysisCsv, readAnalysisJson } from "@/lib/stand-in/data-files";
13: import type { TractColumn } from "@/lib/tract-columns";
14: 
15: const JEV = "typesafe-ai/jev";
16: const TIMEOUT_MS = 20_000;
17: 
18: /**
19:  * The answer levels for every column, from against to for. A column can count
20:  * against a customer as well as for one: high incomes suit an affluent
21:  * audience and not a low-income one, and median age points opposite ways for
22:  * young and older audiences. So the level keeps its direction, and the weight
23:  * runs from -1 to 1.
24:  */
25: const LEVELS = [
26:   "Strongly against: the target customers are much less likely to have this trait.",
27:   "Against: the target customers are somewhat less likely to have this trait.",
28:   "Not relevant: the description says nothing either way about this trait.",
29:   "For: the target customers are somewhat more likely to have this trait.",
30:   "Strongly for: the target customers are much more likely to have this trait.",
31: ];
32: 
33: /**
34:  * The answer as a weight from -1 to 1. With per-level probabilities this is
35:  * the expected level, so a split between "for" and "strongly for" lands
36:  * between them; otherwise it is the single level Jev chose.
37:  */
38: function toWeight(answer: { score: number; probabilities?: Record<string, number> }) {
39:   const top = LEVELS.length - 1;
40:   let level = answer.score;
41:   const entries = Object.entries(answer.probabilities ?? {})
42:     .map(([key, p]) => [Number(key), p] as const)
43:     .filter(([i, p]) => Number.isInteger(i) && i >= 0 && i <= top && Number.isFinite(p));
44:   const total = entries.reduce((sum, [, p]) => sum + p, 0);
45:   if (total > 0) level = entries.reduce((sum, [i, p]) => sum + i * p, 0) / total;
46:   return Number(Math.max(-1, Math.min(1, (level / top) * 2 - 1)).toFixed(2));
47: }
48: 
49: async function jevWeights(columns: TractColumn[], brief: Brief): Promise<ColumnWeight[]> {
50:   const result = await decide({
51:     model: JEV,
52:     state: {
53:       "target customer": brief.targetCustomer,
54:       startup: brief.description,
55:       industry: brief.industry,
56:     },
57:     questions: Object.fromEntries(
58:       columns.map((c) => [
59:         c.name,
60:         {
61:           type: "score" as const,
62:           instructions: `How does this trait of an area's ${c.measures === "lives" ? "residents" : c.measures === "works" ? "workers" : "passers-by"} relate to the startup's target customers? Trait: ${c.description}.`,
63:           criteria: LEVELS,
64:         },
65:       ]),
66:     ),
67:     abortSignal: AbortSignal.timeout(TIMEOUT_MS),
68:   });
69: 
70:   return columns.map((c) => {
71:     const answer = result.answers[c.name];
72:     if (answer?.type !== "score") throw new Error(`Jev returned no score for "${c.name}".`);
73:     return { column: c.name, description: c.description, measures: c.measures, weight: toWeight(answer) };
74:   });
75: }
76: 
77: export async function scoreAudience(brief: Brief): Promise<AudienceFit> {
78:   const [columns, tracts] = await Promise.all([
79:     readAnalysisJson<TractColumn[]>("columns.json"),
80:     readAnalysisCsv("nyc_tracts.csv"),
81:   ]);
82: 
83:   // Without gateway credentials, or if Jev fails, the keyword stand-in keeps
84:   // the page working, and `source` tells the page which one it got. Locally the
85:   // credential is AI_GATEWAY_API_KEY; on a Vercel deployment the AI SDK uses
86:   // the project's OIDC token when no key is set.
87:   let weights: ColumnWeight[];
88:   let source: AudienceFit["source"] = "jev";
89:   if (!process.env.AI_GATEWAY_API_KEY && !process.env.VERCEL_OIDC_TOKEN) {
90:     console.warn("No AI_GATEWAY_API_KEY or VERCEL_OIDC_TOKEN; weighting the audience by keywords instead of Jev.");
91:     weights = keywordWeights(columns, brief.targetCustomer);
92:     source = "keywords";
93:   } else {
94:     try {
95:       weights = await jevWeights(columns, brief);
96:     } catch (error) {
97:       console.error("Jev failed; weighting the audience by keywords instead.", error);
98:       weights = keywordWeights(columns, brief.targetCustomer);
99:       source = "keywords";
100:     }
101:   }
102: 
103:   const markets = new Set<string>(brief.markets);
104:   const raw: [string, number][] = [];
105:   for (const tract of tracts) {
106:     if (!markets.has(tract.borough)) continue;
107:     let sum = 0;
108:     let magnitude = 0;
109:     for (const [i, w] of weights.entries()) {
110:       if (w.weight === 0) continue;
111:       sum += w.weight * Number(tract[columns[i].scaled]);
112:       magnitude += Math.abs(w.weight);
113:     }
114:     raw.push([tract.geoid, magnitude ? sum / magnitude : 0]);
115:   }
116: 
117:   // Rescale by rank so the strongest tracts reach 1 whatever the weights.
118:   raw.sort((a, b) => a[1] - b[1]);
119:   const scores: Record<string, number> = {};
120:   raw.forEach(([geoid], i) => {
121:     scores[geoid] = Number((i / Math.max(raw.length - 1, 1)).toFixed(4));
122:   });
123: 
124:   return { weights, scores, source };
125: }

