1: "use server";
2: 
3: // Stand-in for the placement Server Function. It reads the real kiosks and
4: // shelters, but invents their costs, measurement methods and minimum spends.
5: 
6: import type { Borough, Placement, PlacementQuery } from "@/lib/contract";
7: 
8: import { delay, hashUnit, readAnalysisCsv } from "./data-files";
9: 
10: const MEASUREMENTS: Placement["measurement"][] = ["QR code", "promo code", "landing page"];
11: 
12: export async function findPlacements(query: PlacementQuery): Promise<Placement[]> {
13:   const rows = await readAnalysisCsv("nyc_placements.csv");
14:   const rank = new Map(query.geoids.map((g, i) => [g, i]));
15: 
16:   const placements: Placement[] = rows
17:     .filter((r) => rank.has(r.geoid) && r.carries_ads !== "no")
18:     .map((r) => {
19:       const base = r.kind === "linknyc" ? 0.02 : 0.035;
20:       return {
21:         id: r.placement_id,
22:         kind: r.kind as Placement["kind"],
23:         address: r.address,
24:         borough: r.borough as Borough,
25:         latitude: Number(r.latitude),
26:         longitude: Number(r.longitude),
27:         geoid: r.geoid,
28:         carriesAds: r.carries_ads as Placement["carriesAds"],
29:         costPerAudienceMember: Number((base * (0.6 + hashUnit(r.placement_id))).toFixed(3)),
30:         measurement: MEASUREMENTS[Math.floor(hashUnit(r.placement_id + "m") * 3)],
